#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gramschmidt.h"

/* --------------------------------------------------------------------
 * Tunable parameters for the optimized kernel
 * --------------------------------------------------------------------
 * GRAMSCHMIDT_OMP_MIN_WORK controls when we enable OpenMP parallelism
 * over the j-loop (columns) for a given k. It is expressed as a
 * rough count of floating-point operations:
 *   work_k ≈ M * (N - k - 1)
 * For small problems, spawning threads costs more than it saves,
 * so we only parallelize when work_k exceeds this threshold.
 */
#ifndef GRAMSCHMIDT_OMP_MIN_WORK
# define GRAMSCHMIDT_OMP_MIN_WORK 32768LL
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
      Q[i][j] = 0.0;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      R[i][j] = 0.0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
 http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  /* Use PolyBench's preprocessed problem sizes (_PB_M, _PB_N)
     as loop bounds to preserve original semantics within the
     SCoP region. */
  const int pb_m = _PB_M;
  const int pb_n = _PB_N;

  /* Temporary contiguous buffer to hold a single column of A and the
   * corresponding column of Q during processing.
   *
   * Motivation:
   *  - In C, matrices are row-major. Accessing A[i][k] for varying i
   *    is inherently strided and cache-unfriendly.
   *  - We gather column k of A into a contiguous buffer `colA`,
   *    compute its norm, normalize it (this becomes q_k), and then
   *    use `colA` for all dot products and updates involving q_k.
   *  - This avoids re-loading A[i][k] multiple times and improves
   *    spatial locality and vectorization opportunities.
   *
   * Memory overhead is O(M), which is well below the 50% overhead
   * limit relative to the original O(MN + N^2) data footprint.
   */
  DATA_TYPE* restrict colA =
    (DATA_TYPE*)polybench_alloc_data((unsigned long long)pb_m,
                                     sizeof(DATA_TYPE));

#pragma scop
  for (k = 0; k < pb_n; k++)
    {
      /* 1. Gather column k of A and compute its 2-norm. */
      DATA_TYPE nrm = SCALAR_VAL(0.0);

      for (i = 0; i < pb_m; i++)
      {
        DATA_TYPE a_ik = A[i][k];
        colA[i] = a_ik;
        nrm += a_ik * a_ik;
      }

      /* 2. Compute R[k][k] and normalize the gathered column.
       *
       * We explicitly compute the reciprocal of R[k][k] once and
       * use a multiplication for each element instead of a division.
       * This reduces the number of expensive division operations
       * without changing the mathematical result.
       */
      DATA_TYPE Rkk = SQRT_FUN(nrm);
      R[k][k] = Rkk;

      DATA_TYPE invR = SCALAR_VAL(1.0) / Rkk;

      /* Normalize: colA[i] <- colA[i] / Rkk, i.e., colA now holds Q[:,k]. */
      for (i = 0; i < pb_m; i++)
        colA[i] *= invR;

      /* 3. Orthogonalize remaining columns j > k against q_k
       *    stored in colA.
       *
       *    For each column j:
       *      R[k][j] = q_k^T * A[:, j]
       *      A[:, j] = A[:, j] - q_k * R[k][j]
       *
       * Columns j are independent for fixed k, so we parallelize
       * the j-loop with OpenMP. Each thread works on distinct
       * columns A[:, j] and R[k][j], all reading the shared,
       * read-only vector colA (q_k).
       *
       * An `if` clause avoids parallel overhead for very small
       * problem sizes.
       */
      long long work_k =
        (long long)pb_m * (long long)(pb_n - (k + 1));

#pragma omp parallel for schedule(static) if (work_k > GRAMSCHMIDT_OMP_MIN_WORK)
      for (j = k + 1; j < pb_n; j++)
      {
        DATA_TYPE rkj = SCALAR_VAL(0.0);

        /* Compute R[k][j] = q_k^T * A[:,j]. */
        for (i = 0; i < pb_m; i++)
          rkj += colA[i] * A[i][j];

        R[k][j] = rkj;

        /* Update A[:,j] -= q_k * R[k][j]. */
        for (i = 0; i < pb_m; i++)
          A[i][j] -= colA[i] * rkj;
      }

      /* 4. Scatter normalized q_k from the contiguous buffer back
       *    into the Q matrix.
       *
       *    Semantically, this is equivalent to the original code,
       *    which stored Q[i][k] before processing columns j>k.
       *    Here we delay the (strided) scatter, but all uses of
       *    Q[:,k] in the algorithm are via the local buffer colA,
       *    so the results in A, Q, and R are unchanged modulo the
       *    usual floating-point round-off.
       */
      for (i = 0; i < pb_m; i++)
        Q[i][k] = colA[i];
    }
#pragma endscop

  /* Release temporary buffer. */
  POLYBENCH_FREE_ARRAY(colA);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(R,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(Q,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(R),
	      POLYBENCH_ARRAY(Q));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gramschmidt (m, n,
		      POLYBENCH_ARRAY(A),
		      POLYBENCH_ARRAY(R),
		      POLYBENCH_ARRAY(Q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(R), POLYBENCH_ARRAY(Q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(R);
  POLYBENCH_FREE_ARRAY(Q);

  return 0;
}
