    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Create local restrict-qualified views of the 2D arrays.
     This gives the compiler stronger aliasing information and can
     improve vectorization and cache utilization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict R_)[n] = R;
  DATA_TYPE (*restrict Q_)[n] = Q;

  /* Temporary contiguous buffer for the current column k of Q.
     Accessing a column of a row-major matrix is naturally strided;
     by copying it once into a contiguous buffer, all subsequent
     inner-loop accesses become cache-friendly and easier to vectorize.
     Size m is small compared to the full matrices, so this stays well
     within the 50% extra memory budget. */
  DATA_TYPE *restrict qk =
    (DATA_TYPE*) polybench_alloc_data((unsigned long long)m,
                                      sizeof(DATA_TYPE));

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* 1) Compute the Euclidean norm of column k of A. */
      nrm = SCALAR_VAL(0.0);

      /* Parallelizable reduction over rows (i).
         - 'reduction(+:nrm)' keeps the mathematical sum while allowing
           different threads to accumulate partial sums.
         - The 'if' clause avoids threading overhead on tiny problems.
         - When compiled without OpenMP support, this pragma is ignored
           and execution remains sequential. */
#pragma omp parallel for reduction(+:nrm) if (_PB_M >= 64)
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE aik = A_[i][k];
          nrm += aik * aik;
        }

      R_[k][k] = SQRT_FUN(nrm);

      /* Precompute the reciprocal of R[k][k] so that the next loop uses
         multiplications instead of divisions. This is mathematically
         equivalent to dividing each element by R[k][k], though floating
         point rounding will differ slightly. */
      DATA_TYPE inv_rkk = SCALAR_VAL(1.0) / R_[k][k];

      /* 2) Normalize column k of A to obtain column k of Q.
         At the same time, copy the column into qk so that the following
         orthogonalization step can reuse Q[:,k] from a contiguous buffer
         instead of repeatedly doing strided loads from Q. */
#pragma omp parallel for if (_PB_M >= 64)
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE q = A_[i][k] * inv_rkk;
          Q_[i][k] = q;
          qk[i]    = q;
        }

      /* 3) Orthogonalize remaining columns j > k with respect to Q[:,k].
         Each column j is independent and can be processed in parallel. */
#pragma omp parallel for private(i) if (_PB_M >= 64)
      for (j = k + 1; j < _PB_N; j++)
        {
          DATA_TYPE rkj = SCALAR_VAL(0.0);

          /* Compute R[k][j] = dot(Q[:,k], A[:,j]).  Using qk[] here
             avoids strided accesses to Q and keeps the inner loop
             strictly streaming through A[:,j]. */
          for (i = 0; i < _PB_M; i++)
            rkj += qk[i] * A_[i][j];

          R_[k][j] = rkj;

          /* Update A[:,j] = A[:,j] - Q[:,k] * R[k][j].  Again we reuse
             qk[] so the loop only streams through A. */
          for (i = 0; i < _PB_M; i++)
            A_[i][j] -= qk[i] * rkj;
        }
    }
#pragma endscop

  /* Release temporary buffer. */
  polybench_free_data(qk);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
