   http://www.inf.ethz.ch/personal/gander/

   Optimizations:
   - Use restrict-qualified local aliases for A, R, Q to help the compiler
     with alias analysis and vectorization.
   - Introduce a temporary contiguous buffer qk[] that holds the k-th column
     of Q. This greatly improves data locality when reusing that column in
     the inner loops over j and i, and eliminates repeated strided loads
     from Q.
   - Add OpenMP pragmas to exploit parallelism along i (for the norm and
     normalization) and along j (for independent column updates).
   - Replace repeated divisions by R[k][k] with a single division and
     reuse the result, while preserving the mathematical computation.
*/
static void __attribute__((noinline))
kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Local restrict-qualified aliases to help the optimizer.
     The polybench 2D macros give us VLA types A[m][n], etc.,
     so we can safely create pointer aliases parameterized by n. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict R_)[n] = R;
  DATA_TYPE (*restrict Q_)[n] = Q;

  /* Temporary buffer for the current column of Q.
     Size is _PB_M, the effective loop bound used in the kernel.
     This adds only O(M) extra storage (< 50% of the original footprint). */
  DATA_TYPE qk[_PB_M];

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* -------------------------------------------------------------------
       * 1. Compute the Euclidean norm of column k of A.
       *    nrm = sum_i A[i][k]^2
       * ------------------------------------------------------------------- */
      nrm = SCALAR_VAL(0.0);

      /* Parallelize over rows when there is enough work. */
#pragma omp parallel for reduction(+:nrm) if (_PB_M >= GRAMSCHMIDT_OMP_MIN_M)
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE aik = A_[i][k];
          nrm += aik * aik;
        }

      R_[k][k] = SQRT_FUN(nrm);

      /* -------------------------------------------------------------------
       * 2. Normalize the k-th column: Q[:,k] = A[:,k] / R[k][k]
       *    At the same time, copy it into qk[] so that we have a contiguous
       *    buffer for repeated use in the inner loops that follow.
       *
       *    Using qk[] avoids repeatedly streaming the same strided column
       *    of Q from memory for each j>k; instead we read it once and
       *    subsequently reuse it from a small, cache-friendly buffer.
       * ------------------------------------------------------------------- */
#pragma omp parallel for if (_PB_M >= GRAMSCHMIDT_OMP_MIN_M)
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE q_val = A_[i][k] / R_[k][k];
          Q_[i][k] = q_val;
          qk[i]    = q_val;
        }

      /* -------------------------------------------------------------------
       * 3. For all remaining columns j > k, compute:
       *        R[k][j] = Q[:,k]^T * A[:,j]
       *        A[:,j]  = A[:,j] - Q[:,k] * R[k][j]
       *
       *    Columns j are independent of each other in this step, so we
       *    parallelize over j. Inside each j-iteration we walk over i in
       *    the same order as the original code, preserving the order of
       *    floating-point operations for each dot product.
       *
       *    We use qk[] instead of Q_[:,k] to improve cache locality.
       * ------------------------------------------------------------------- */
#pragma omp parallel for private(i) if (((_PB_N - (k + 1)) * (long)_PB_M) >= GRAMSCHMIDT_OMP_MIN_WORK)
      for (j = k + 1; j < _PB_N; j++)
        {
          DATA_TYPE rkj = SCALAR_VAL(0.0);

          /* Compute R[k][j] = sum_i qk[i] * A[i][j]. */
          for (i = 0; i < _PB_M; i++)
            {
              rkj += qk[i] * A_[i][j];
            }

          R_[k][j] = rkj;

          /* Update A[:,j] = A[:,j] - qk[:] * rkj. */
          for (i = 0; i < _PB_M; i++)
            {
              A_[i][j] -= qk[i] * rkj;
            }
        }
    }
#pragma endscop
}


