/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* ------------------------------------------------------------
       * 1. Compute the 2-norm of the k-th column of A.
       *    nrm = sum_i A[i][k]^2
       *    This loop is parallelized as a reduction over rows.
       * ------------------------------------------------------------ */
      nrm = SCALAR_VAL(0.0);

#pragma omp parallel for reduction(+:nrm) if (_PB_M > 256)
      for (i = 0; i < _PB_M; i++)
      {
        DATA_TYPE val = A[i][k];
        nrm += val * val;
      }

      /* ------------------------------------------------------------
       * 2. Normalize column k to obtain Q[:,k].
       *    R[k][k] = sqrt(nrm)
       *    Q[i][k] = A[i][k] / R[k][k]
       *
       *    Use a reciprocal (invRkk) and multiplication instead of
       *    repeated division to reduce the cost of the operation.
       *    This is mathematically equivalent:
       *    Q[i][k] = A[i][k] * (1 / R[k][k])
       * ------------------------------------------------------------ */
      DATA_TYPE Rkk = SQRT_FUN(nrm);
      R[k][k] = Rkk;

      DATA_TYPE invRkk = SCALAR_VAL(1.0) / Rkk;

#pragma omp parallel for if (_PB_M > 256)
      for (i = 0; i < _PB_M; i++)
      {
        Q[i][k] = A[i][k] * invRkk;
      }

      /* ------------------------------------------------------------
       * 3. Compute R[k][j] = dot(Q[:,k], A[:,j]) for j = k+1..N-1.
       *
       * Original code:
       *   for j = k+1..N-1:
       *     R[k][j] = 0;
       *     for i = 0..M-1:
       *       R[k][j] += Q[i][k] * A[i][j];
       *
       * We keep the same accumulation order per (k,j) pair (i = 0..M-1),
       * but transform the traversal to improve cache locality:
       *
       *   - First zero the whole trailing part of R's k-th row.
       *   - Then iterate with i as the outer loop and j as the inner loop:
       *
       *     for i:
       *       q_ik = Q[i][k];
       *       for j:
       *         R[k][j] += q_ik * A[i][j];
       *
       * For each fixed j, the sequence of updates to R[k][j] still
       * occurs in the order i = 0..M-1, so the floating-point
       * accumulation order for each dot product is preserved.
       *
       * Having j as the inner loop yields contiguous accesses to
       * A[i][j] (row-major layout), significantly improving data
       * locality compared to the original column-wise traversal.
       * ------------------------------------------------------------ */

      /* Pointer to the k-th row of R for quick indexed access. */
      DATA_TYPE *Rk = R[k];

      /* Initialize the trailing part of row k. */
      for (j = k + 1; j < _PB_N; j++)
        Rk[j] = SCALAR_VAL(0.0);

      /* Accumulate dot products into Rk[j]. This loop is kept
         sequential due to per-element reductions on Rk[j]; changing
         that would require additional temporary buffers. */
      for (i = 0; i < _PB_M; i++)
      {
        const DATA_TYPE  q_ik = Q[i][k];
        const DATA_TYPE *Ai   = A[i];  /* pointer to row i of A */

        for (j = k + 1; j < _PB_N; j++)
        {
          Rk[j] += q_ik * Ai[j];
        }
      }

      /* ------------------------------------------------------------
       * 4. Update trailing columns of A:
       *      A[i][j] = A[i][j] - Q[i][k] * R[k][j],  j = k+1..N-1
       *
       * This is a rank-1 update on the trailing submatrix of A.
       *
       * We iterate with i as the outer loop and j as the inner loop
       * for better cache locality (row-major layout). Each (i,j)
       * update is independent, so we parallelize over i.
       * ------------------------------------------------------------ */
